/**
 * Event Bus — in-memory publish/subscribe
 * All inter-service communication flows through here.
 */

type Callback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Callback[]> = new Map();

  subscribe(event: string, callback: Callback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  publish(event: string, payload: any): void {
    const handlers = this.subscribers.get(event);
    if (!handlers || handlers.length === 0) return;
    for (const handler of handlers) {
      try {
        handler(payload);
      } catch (err) {
        console.error(`[EventBus] Error in handler for event "${event}":`, err);
      }
    }
  }
}

/**
 * User Service
 * Owns the user data store exclusively.
 * Data shape: { id, name, email }
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(data: { name: string; email: string }): User {
    if (!data.name || !data.email) {
      throw new Error("name and email are required");
    }
    const user: User = {
      id: randomUUID(),
      name: data.name,
      email: data.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new Error(`User not found: ${id}`);
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, data: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    if (data.name !== undefined) user.name = data.name;
    if (data.email !== undefined) user.email = data.email;
    this.store.set(id, user);
    return user;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`User not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Project Service
 * Owns the project data store exclusively.
 * Data shape: { id, name, description, memberIds[] }
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(data: { name: string; description: string }): Project {
    if (!data.name) throw new Error("name is required");
    const project: Project = {
      id: randomUUID(),
      name: data.name,
      description: data.description ?? "",
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) throw new Error(`Project not found: ${id}`);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(
    id: string,
    data: Partial<{ name: string; description: string }>
  ): Project {
    const project = this.getById(id);
    if (data.name !== undefined) project.name = data.name;
    if (data.description !== undefined) project.description = data.description;
    this.store.set(id, project);
    return project;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Project not found: ${id}`);
    this.store.delete(id);
  }

  addMember(id: string, userId: string): Project {
    const project = this.getById(id);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.store.set(id, project);
    }
    return project;
  }

  removeMember(id: string, userId: string): Project {
    const project = this.getById(id);
    project.memberIds = project.memberIds.filter((mid) => mid !== userId);
    this.store.set(id, project);
    return project;
  }
}

/**
 * Task Service
 * Owns the task data store exclusively.
 * Data shape: { id, title, description, status, assigneeId, projectId }
 *
 * Publishes:
 *   task.assigned       → { taskId, taskTitle, assigneeId }
 *   task.statusChanged  → { taskId, taskTitle, assigneeId, oldStatus, newStatus }
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";

const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();

  constructor(private eventBus: EventBus) {}

  create(data: {
    title: string;
    description?: string;
    projectId: string;
    assigneeId?: string;
  }): Task {
    if (!data.title) throw new Error("title is required");
    if (!data.projectId) throw new Error("projectId is required");

    const task: Task = {
      id: randomUUID(),
      title: data.title,
      description: data.description ?? "",
      status: "todo",
      assigneeId: data.assigneeId ?? null,
      projectId: data.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    return task;
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(
    id: string,
    data: Partial<{ title: string; description: string; projectId: string }>
  ): Task {
    const task = this.getById(id);
    if (data.title !== undefined) task.title = data.title;
    if (data.description !== undefined) task.description = data.description;
    if (data.projectId !== undefined) task.projectId = data.projectId;
    this.store.set(id, task);
    return task;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Task not found: ${id}`);
    this.store.delete(id);
  }

  assign(id: string, assigneeId: string): Task {
    const task = this.getById(id);
    task.assigneeId = assigneeId;
    this.store.set(id, task);

    this.eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    });

    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getById(id);
    const oldIndex = STATUS_ORDER.indexOf(task.status);
    const newIndex = STATUS_ORDER.indexOf(newStatus);

    if (newIndex === -1) {
      throw new Error(`Invalid status: ${newStatus}`);
    }
    if (newIndex <= oldIndex) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". Only forward transitions are allowed (todo → in-progress → done).`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(id, task);

    this.eventBus.publish("task.statusChanged", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }
}

/**
 * Comment Service
 * Owns the comment data store exclusively.
 * Data shape: { id, taskId, authorId, body, createdAt }
 *
 * Publishes:
 *   comment.added → { commentId, taskId, taskTitle, authorId, authorName }
 *
 * NOTE: taskTitle and authorName are supplied by the router/caller at creation
 * time (they are resolved via their respective services in the router layer),
 * keeping this service free of direct service-to-service calls.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus) {}

  create(data: {
    taskId: string;
    authorId: string;
    body: string;
    /** Resolved by the router for the event payload */
    taskTitle: string;
    /** Resolved by the router for the event payload */
    authorName: string;
  }): Comment {
    if (!data.taskId) throw new Error("taskId is required");
    if (!data.authorId) throw new Error("authorId is required");
    if (!data.body) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId,
      authorId: data.authorId,
      body: data.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: data.taskId,
      taskTitle: data.taskTitle,
      authorId: data.authorId,
      authorName: data.authorName,
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Notification Service
 * Owns the notification data store exclusively.
 * Data shape: { id, userId, message, read, createdAt }
 *
 * Subscribes to:
 *   task.assigned       → creates notification for assignee
 *   task.statusChanged  → creates notification for assignee
 *   comment.added       → creates notification for task assignee
 *                         (assigneeId is embedded in the event payload)
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(private eventBus: EventBus) {
    this.registerSubscriptions();
  }

  private registerSubscriptions(): void {
    this.eventBus.subscribe("task.assigned", (payload) => {
      const { taskId, taskTitle, assigneeId } = payload as {
        taskId: string;
        taskTitle: string;
        assigneeId: string;
      };
      this.createNotification(
        assigneeId,
        `You have been assigned to task "${taskTitle}" (${taskId}).`
      );
    });

    this.eventBus.subscribe("task.statusChanged", (payload) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } =
        payload as {
          taskId: string;
          taskTitle: string;
          assigneeId: string | null;
          oldStatus: string;
          newStatus: string;
        };
      if (!assigneeId) return; // no assignee — nobody to notify
      this.createNotification(
        assigneeId,
        `Task "${taskTitle}" (${taskId}) status changed from "${oldStatus}" to "${newStatus}".`
      );
    });

    this.eventBus.subscribe("comment.added", (payload) => {
      const { commentId, taskId, taskTitle, authorId, authorName } =
        payload as {
          commentId: string;
          taskId: string;
          taskTitle: string;
          authorId: string;
          authorName: string;
          /** Provided by the router so the notification service doesn't need
           *  to call the task service directly. */
          assigneeId?: string | null;
        };

      // The router embeds assigneeId in the comment.added payload so we
      // can notify the task's assignee without reaching into another service.
      const assigneeId = (payload as any).assigneeId as string | null | undefined;
      if (!assigneeId) return;

      this.createNotification(
        assigneeId,
        `${authorName} commented on task "${taskTitle}" (${taskId}): "${payload.body ?? "…"}".`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new Error(`Notification not found: ${id}`);
    notification.read = true;
    this.store.set(id, notification);
    return notification;
  }
}

/**
 * API Router
 * Single HTTP entry point. Parses requests, delegates to services, returns JSON.
 * Uses only Node.js built-in `http` module — no frameworks.
 */

import { IncomingMessage, ServerResponse } from "http";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk) => (raw += chunk));
    req.on("end", () => {
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function send(res: ServerResponse, status: number, data: unknown): void {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function ok(res: ServerResponse, data: unknown): void {
  send(res, 200, data);
}

function created(res: ServerResponse, data: unknown): void {
  send(res, 201, data);
}

function notFound(res: ServerResponse, message = "Not found"): void {
  send(res, 404, { error: message });
}

function badRequest(res: ServerResponse, message: string): void {
  send(res, 400, { error: message });
}

function methodNotAllowed(res: ServerResponse): void {
  send(res, 405, { error: "Method not allowed" });
}

function parsePathAndQuery(req: IncomingMessage): {
  segments: string[];
  query: Record<string, string>;
} {
  const raw = req.url ?? "/";
  const qIdx = raw.indexOf("?");
  const pathPart = qIdx === -1 ? raw : raw.slice(0, qIdx);
  const queryPart = qIdx === -1 ? "" : raw.slice(qIdx + 1);

  const segments = pathPart.split("/").filter(Boolean);

  const query: Record<string, string> = {};
  if (queryPart) {
    for (const pair of queryPart.split("&")) {
      const eqIdx = pair.indexOf("=");
      if (eqIdx === -1) continue;
      const key = decodeURIComponent(pair.slice(0, eqIdx));
      const val = decodeURIComponent(pair.slice(eqIdx + 1));
      query[key] = val;
    }
  }

  return { segments, query };
}

// ---------------------------------------------------------------------------
// Router factory
// ---------------------------------------------------------------------------

export function createRouter(
  userService: UserService,
  projectService: ProjectService,
  taskService: TaskService,
  commentService: CommentService,
  notificationService: NotificationService
) {
  return async function handler(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const method = req.method?.toUpperCase() ?? "GET";
    const { segments, query } = parsePathAndQuery(req);

    try {
      // -----------------------------------------------------------------------
      // /users  and  /users/:id
      // -----------------------------------------------------------------------
      if (segments[0] === "users") {
        const id = segments[1];

        if (!id) {
          // /users
          if (method === "GET") return ok(res, userService.getAll());
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, userService.create(body));
          }
          return methodNotAllowed(res);
        }

        // /users/:id
        if (method === "GET") return ok(res, userService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, userService.update(id, body));
        }
        if (method === "DELETE") {
          userService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /projects  and  /projects/:id  and  /projects/:id/members
      // -----------------------------------------------------------------------
      if (segments[0] === "projects") {
        const id = segments[1];
        const sub = segments[2]; // e.g. "members"

        if (!id) {
          // /projects
          if (method === "GET") return ok(res, projectService.getAll());
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, projectService.create(body));
          }
          return methodNotAllowed(res);
        }

        if (sub === "members") {
          // /projects/:id/members
          if (method === "POST") {
            const body = await readBody(req);
            return ok(res, projectService.addMember(id, body.userId));
          }
          if (method === "DELETE") {
            const body = await readBody(req);
            return ok(res, projectService.removeMember(id, body.userId));
          }
          return methodNotAllowed(res);
        }

        // /projects/:id
        if (method === "GET") return ok(res, projectService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, projectService.update(id, body));
        }
        if (method === "DELETE") {
          projectService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /tasks  and  /tasks/:id  and  /tasks/:id/status  /tasks/:id/assign
      // -----------------------------------------------------------------------
      if (segments[0] === "tasks") {
        const id = segments[1];
        const sub = segments[2]; // "status" | "assign"

        if (!id) {
          // /tasks  or  /tasks?projectId=X
          if (method === "GET") {
            if (query.projectId) {
              return ok(res, taskService.getByProject(query.projectId));
            }
            return ok(res, taskService.getAll());
          }
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, taskService.create(body));
          }
          return methodNotAllowed(res);
        }

        if (sub === "status") {
          // /tasks/:id/status
          if (method === "PUT") {
            const body = await readBody(req);
            return ok(res, taskService.changeStatus(id, body.status));
          }
          return methodNotAllowed(res);
        }

        if (sub === "assign") {
          // /tasks/:id/assign
          if (method === "PUT") {
            const body = await readBody(req);
            return ok(res, taskService.assign(id, body.assigneeId));
          }
          return methodNotAllowed(res);
        }

        // /tasks/:id
        if (method === "GET") return ok(res, taskService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, taskService.update(id, body));
        }
        if (method === "DELETE") {
          taskService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /comments  and  /comments/:id
      // -----------------------------------------------------------------------
      if (segments[0] === "comments") {
        const id = segments[1];

        if (!id) {
          // /comments  or  /comments?taskId=X
          if (method === "GET") {
            if (query.taskId) {
              return ok(res, commentService.getByTask(query.taskId));
            }
            return ok(res, commentService.getByTask("")); // returns [] for empty
          }
          if (method === "POST") {
            const body = await readBody(req);

            // Resolve enrichment data here in the router so that the comment
            // service never has to call the task or user service directly.
            const task = taskService.getById(body.taskId);
            const user = userService.getById(body.authorId);

            const comment = commentService.create({
              taskId: body.taskId,
              authorId: body.authorId,
              body: body.body,
              taskTitle: task.title,
              authorName: user.name,
            });

            // Also attach assigneeId into the event so NotificationService
            // can notify the task assignee without reaching across services.
            // We do this by publishing a supplemental payload via a wrapper:
            // The comment service already fired comment.added; we patch the
            // notification by leveraging the fact that we passed assigneeId
            // through the enriched create call below.
            // → See revised approach: we re-publish with assigneeId included.

            return created(res, comment);
          }
          return methodNotAllowed(res);
        }

        // /comments/:id
        if (method === "GET") return ok(res, commentService.getById(id));
        if (method === "DELETE") {
          commentService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /notifications?userId=X  and  /notifications/:id/read
      // -----------------------------------------------------------------------
      if (segments[0] === "notifications") {
        const id = segments[1];
        const sub = segments[2]; // "read"

        if (!id) {
          // /notifications?userId=X
          if (method === "GET") {
            if (!query.userId) return badRequest(res, "userId query param required");
            return ok(res, notificationService.getByUser(query.userId));
          }
          return methodNotAllowed(res);
        }

        if (sub === "read") {
          // /notifications/:id/read
          if (method === "PUT") {
            return ok(res, notificationService.markAsRead(id));
          }
          return methodNotAllowed(res);
        }

        return notFound(res);
      }

      // -----------------------------------------------------------------------
      // 404 fallback
      // -----------------------------------------------------------------------
      notFound(res, `Route not found: ${method} /${segments.join("/")}`);
    } catch (err: any) {
      const message: string = err?.message ?? "Internal server error";
      // Distinguish user errors from true server errors
      const status =
        message.includes("not found") || message.includes("Not found")
          ? 404
          : message.includes("Invalid") || message.includes("required") || message.includes("transition")
          ? 400
          : 500;
      send(res, status, { error: message });
    }
  };
}

/**
 * Comment Service
 * Owns the comment data store exclusively.
 * Data shape: { id, taskId, authorId, body, createdAt }
 *
 * Publishes:
 *   comment.added → { commentId, taskId, taskTitle, authorId, authorName, assigneeId }
 *
 * taskTitle, authorName, and assigneeId are resolved by the router and passed
 * in at creation time, keeping this service free of direct service-to-service
 * calls.  assigneeId is forwarded in the event payload so that
 * NotificationService can notify the task's current assignee.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private eventBus: EventBus) {}

  create(data: {
    taskId: string;
    authorId: string;
    body: string;
    /** Resolved by the router — forwarded in the event payload only */
    taskTitle: string;
    /** Resolved by the router — forwarded in the event payload only */
    authorName: string;
    /** Resolved by the router — forwarded in the event payload so
     *  NotificationService can notify the assignee */
    assigneeId: string | null;
  }): Comment {
    if (!data.taskId) throw new Error("taskId is required");
    if (!data.authorId) throw new Error("authorId is required");
    if (!data.body) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId,
      authorId: data.authorId,
      body: data.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: data.taskId,
      taskTitle: data.taskTitle,
      authorId: data.authorId,
      authorName: data.authorName,
      assigneeId: data.assigneeId,
      // Include a snippet of the body so notification messages are richer
      body: data.body,
    });

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * API Router
 * Single HTTP entry point. Parses requests, delegates to services, returns JSON.
 * Uses only Node.js built-in `http` module — no frameworks.
 */

import { IncomingMessage, ServerResponse } from "http";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService, TaskStatus } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function readBody(req: IncomingMessage): Promise<Record<string, any>> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk: Buffer) => (raw += chunk.toString()));
    req.on("end", () => {
      if (!raw.trim()) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function send(res: ServerResponse, status: number, data: unknown): void {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function ok(res: ServerResponse, data: unknown): void {
  send(res, 200, data);
}

function created(res: ServerResponse, data: unknown): void {
  send(res, 201, data);
}

function notFound(res: ServerResponse, message = "Not found"): void {
  send(res, 404, { error: message });
}

function badRequest(res: ServerResponse, message: string): void {
  send(res, 400, { error: message });
}

function methodNotAllowed(res: ServerResponse): void {
  send(res, 405, { error: "Method not allowed" });
}

/** Parse URL path segments and query-string parameters. */
function parseRequest(req: IncomingMessage): {
  segments: string[];
  query: Record<string, string>;
} {
  const raw = req.url ?? "/";
  const qIdx = raw.indexOf("?");
  const pathPart = qIdx === -1 ? raw : raw.slice(0, qIdx);
  const queryPart = qIdx === -1 ? "" : raw.slice(qIdx + 1);

  const segments = pathPart.split("/").filter(Boolean);

  const query: Record<string, string> = {};
  if (queryPart) {
    for (const pair of queryPart.split("&")) {
      const eqIdx = pair.indexOf("=");
      if (eqIdx === -1) continue;
      query[decodeURIComponent(pair.slice(0, eqIdx))] =
        decodeURIComponent(pair.slice(eqIdx + 1));
    }
  }

  return { segments, query };
}

/** Map error messages to appropriate HTTP status codes. */
function errorStatus(message: string): number {
  const lower = message.toLowerCase();
  if (lower.includes("not found")) return 404;
  if (
    lower.includes("invalid") ||
    lower.includes("required") ||
    lower.includes("transition") ||
    lower.includes("already")
  )
    return 400;
  return 500;
}

// ---------------------------------------------------------------------------
// Router factory
// ---------------------------------------------------------------------------

export function createRouter(
  userService: UserService,
  projectService: ProjectService,
  taskService: TaskService,
  commentService: CommentService,
  notificationService: NotificationService
) {
  return async function handler(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const method = (req.method ?? "GET").toUpperCase();
    const { segments, query } = parseRequest(req);

    try {
      // -----------------------------------------------------------------------
      // /users  and  /users/:id
      // -----------------------------------------------------------------------
      if (segments[0] === "users") {
        const id = segments[1];

        if (!id) {
          if (method === "GET") return ok(res, userService.getAll());
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, userService.create(body as { name: string; email: string }));
          }
          return methodNotAllowed(res);
        }

        // /users/:id
        if (method === "GET") return ok(res, userService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, userService.update(id, body));
        }
        if (method === "DELETE") {
          userService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /projects  and  /projects/:id  and  /projects/:id/members
      // -----------------------------------------------------------------------
      if (segments[0] === "projects") {
        const id = segments[1];
        const sub = segments[2]; // "members" | undefined

        if (!id) {
          if (method === "GET") return ok(res, projectService.getAll());
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, projectService.create(body as { name: string; description: string }));
          }
          return methodNotAllowed(res);
        }

        if (sub === "members") {
          // /projects/:id/members
          if (method === "POST") {
            const body = await readBody(req);
            return ok(res, projectService.addMember(id, body.userId));
          }
          if (method === "DELETE") {
            const body = await readBody(req);
            return ok(res, projectService.removeMember(id, body.userId));
          }
          return methodNotAllowed(res);
        }

        // /projects/:id
        if (method === "GET") return ok(res, projectService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, projectService.update(id, body));
        }
        if (method === "DELETE") {
          projectService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /tasks  and  /tasks/:id  and  /tasks/:id/status  /tasks/:id/assign
      // -----------------------------------------------------------------------
      if (segments[0] === "tasks") {
        const id = segments[1];
        const sub = segments[2]; // "status" | "assign" | undefined

        if (!id) {
          if (method === "GET") {
            return query.projectId
              ? ok(res, taskService.getByProject(query.projectId))
              : ok(res, taskService.getAll());
          }
          if (method === "POST") {
            const body = await readBody(req);
            return created(res, taskService.create(body as {
              title: string;
              description?: string;
              projectId: string;
              assigneeId?: string;
            }));
          }
          return methodNotAllowed(res);
        }

        if (sub === "status") {
          // /tasks/:id/status
          if (method === "PUT") {
            const body = await readBody(req);
            return ok(res, taskService.changeStatus(id, body.status as TaskStatus));
          }
          return methodNotAllowed(res);
        }

        if (sub === "assign") {
          // /tasks/:id/assign
          if (method === "PUT") {
            const body = await readBody(req);
            return ok(res, taskService.assign(id, body.assigneeId));
          }
          return methodNotAllowed(res);
        }

        // /tasks/:id
        if (method === "GET") return ok(res, taskService.getById(id));
        if (method === "PUT") {
          const body = await readBody(req);
          return ok(res, taskService.update(id, body));
        }
        if (method === "DELETE") {
          taskService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /comments  and  /comments/:id
      // -----------------------------------------------------------------------
      if (segments[0] === "comments") {
        const id = segments[1];

        if (!id) {
          if (method === "GET") {
            if (!query.taskId)
              return badRequest(res, "taskId query param required");
            return ok(res, commentService.getByTask(query.taskId));
          }
          if (method === "POST") {
            const body = await readBody(req);

            // Resolve enrichment data in the router so that neither the
            // CommentService nor the NotificationService must call other
            // services directly — all inter-service data flows through the
            // Event Bus payload.
            const task = taskService.getById(body.taskId);
            const user = userService.getById(body.authorId);

            const comment = commentService.create({
              taskId: body.taskId,
              authorId: body.authorId,
              body: body.body,
              taskTitle: task.title,
              authorName: user.name,
              assigneeId: task.assigneeId, // forwarded in event payload
            });

            return created(res, comment);
          }
          return methodNotAllowed(res);
        }

        // /comments/:id
        if (method === "GET") return ok(res, commentService.getById(id));
        if (method === "DELETE") {
          commentService.delete(id);
          return ok(res, { deleted: true });
        }
        return methodNotAllowed(res);
      }

      // -----------------------------------------------------------------------
      // /notifications?userId=X  and  /notifications/:id/read
      // -----------------------------------------------------------------------
      if (segments[0] === "notifications") {
        const id = segments[1];
        const sub = segments[2]; // "read" | undefined

        if (!id) {
          if (method === "GET") {
            if (!query.userId)
              return badRequest(res, "userId query param required");
            return ok(res, notificationService.getByUser(query.userId));
          }
          return methodNotAllowed(res);
        }

        if (sub === "read") {
          // /notifications/:id/read
          if (method === "PUT") {
            return ok(res, notificationService.markAsRead(id));
          }
          return methodNotAllowed(res);
        }

        return notFound(res);
      }

      // -----------------------------------------------------------------------
      // 404 fallback
      // -----------------------------------------------------------------------
      notFound(res, `Route not found: ${method} /${segments.join("/")}`);
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : "Internal server error";
      send(res, errorStatus(message), { error: message });
    }
  };
}

/**
 * Main entry point
 * Wires all services together and starts the HTTP server.
 */

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { createRouter } from "./router";

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

// 1. Create the event bus (shared communication channel)
const eventBus = new EventBus();

// 2. Instantiate services, injecting the event bus where needed
const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);
// NotificationService registers its event subscriptions in the constructor
const notificationService = new NotificationService(eventBus);

// 3. Build the HTTP request handler
const handler = createRouter(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

// 4. Start the server
const server = createServer(handler);

server.listen(PORT, () => {
  console.log(`Task Management API listening on http://localhost:${PORT}`);
  console.log("Services wired:");
  console.log("  ✓ EventBus");
  console.log("  ✓ UserService");
  console.log("  ✓ ProjectService");
  console.log("  ✓ TaskService");
  console.log("  ✓ CommentService");
  console.log("  ✓ NotificationService");
});

export { server, eventBus, userService, projectService, taskService, commentService, notificationService };

/**
 * Demo Script
 * Starts the server, exercises every feature end-to-end, then shuts down.
 *
 * Run with:  npx tsx src/demo.ts
 *
 * Flow:
 *  1. Create users
 *  2. Create project + add members
 *  3. Create tasks
 *  4. Assign tasks  → triggers task.assigned notification
 *  5. Change task status (todo → in-progress → done)  → notifications
 *  6. Add comments  → comment.added notifications
 *  7. Read notifications for each user
 *  8. Mark notifications as read
 *  9. Edge-case: invalid status transition (expect 400)
 * 10. Clean-up: delete a comment, task, project, user
 */

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { createRouter } from "./router";

// ---------------------------------------------------------------------------
// Spin up an ephemeral server on a random port
// ---------------------------------------------------------------------------
const eventBus = new EventBus();
const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);
const notificationService = new NotificationService(eventBus);

const handler = createRouter(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

const server = createServer(handler);

// ---------------------------------------------------------------------------
// HTTP helper
// ---------------------------------------------------------------------------
function request(
  method: string,
  path: string,
  body?: Record<string, unknown>
): Promise<{ status: number; data: any }> {
  return new Promise((resolve, reject) => {
    const addr = server.address();
    if (!addr || typeof addr === "string") {
      return reject(new Error("Server not ready"));
    }
    const port = addr.port;
    const payload = body ? JSON.stringify(body) : undefined;

    const options = {
      hostname: "127.0.0.1",
      port,
      path,
      method,
      headers: {
        "Content-Type": "application/json",
        ...(payload ? { "Content-Length": Buffer.byteLength(payload) } : {}),
      },
    };

    const { request: httpRequest } = require("http") as typeof import("http");
    const req = httpRequest(options, (res) => {
      let raw = "";
      res.on("data", (chunk: Buffer) => (raw += chunk.toString()));
      res.on("end", () => {
        try {
          resolve({ status: res.statusCode ?? 0, data: JSON.parse(raw) });
        } catch {
          resolve({ status: res.statusCode ?? 0, data: raw });
        }
      });
    });

    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

// ---------------------------------------------------------------------------
// Logging helpers
// ---------------------------------------------------------------------------
const RESET = "\x1b[0m";
const BOLD = "\x1b[1m";
const GREEN = "\x1b[32m";
const YELLOW = "\x1b[33m";
const RED = "\x1b[31m";
const CYAN = "\x1b[36m";

function section(title: string): void {
  console.log(`\n${BOLD}${CYAN}${"─".repeat(60)}${RESET}`);
  console.log(`${BOLD}${CYAN}  ${title}${RESET}`);
  console.log(`${BOLD}${CYAN}${"─".repeat(60)}${RESET}`);
}

function log(label: string, status: number, data: unknown): void {
  const colour = status < 300 ? GREEN : status < 500 ? YELLOW : RED;
  console.log(
    `${colour}[${status}]${RESET} ${BOLD}${label}${RESET}\n` +
      JSON.stringify(data, null, 2)
  );
}

function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(`${RED}${BOLD}ASSERTION FAILED: ${message}${RESET}`);
    process.exit(1);
  }
  console.log(`${GREEN}  ✓ ${message}${RESET}`);
}

// ---------------------------------------------------------------------------
// Main demo
// ---------------------------------------------------------------------------
async function runDemo(): Promise<void> {
  // ── 1. Users ────────────────────────────────────────────────────────────
  section("1. Create Users");

  const { status: s1, data: alice } = await request("POST", "/users", {
    name: "Alice",
    email: "alice@example.com",
  });
  log("POST /users (Alice)", s1, alice);
  assert(s1 === 201, "Alice created (201)");
  assert(alice.id !== undefined, "Alice has an id");

  const { status: s2, data: bob } = await request("POST", "/users", {
    name: "Bob",
    email: "bob@example.com",
  });
  log("POST /users (Bob)", s2, bob);
  assert(s2 === 201, "Bob created (201)");

  const { status: s3, data: users } = await request("GET", "/users");
  log("GET /users", s3, users);
  assert(users.length === 2, "Two users exist");

  // Update a user
  const { status: s4, data: updatedAlice } = await request(
    "PUT",
    `/users/${alice.id}`,
    { name: "Alice A." }
  );
  log("PUT /users/:id (rename Alice)", s4, updatedAlice);
  assert(updatedAlice.name === "Alice A.", "Alice's name updated");

  // ── 2. Project ──────────────────────────────────────────────────────────
  section("2. Create Project & Add Members");

  const { status: s5, data: project } = await request("POST", "/projects", {
    name: "Alpha",
    description: "First project",
  });
  log("POST /projects", s5, project);
  assert(s5 === 201, "Project created (201)");

  const { status: s6, data: projWithAlice } = await request(
    "POST",
    `/projects/${project.id}/members`,
    { userId: alice.id }
  );
  log("POST /projects/:id/members (add Alice)", s6, projWithAlice);
  assert(projWithAlice.memberIds.includes(alice.id), "Alice is a member");

  const { status: s7, data: projWithBob } = await request(
    "POST",
    `/projects/${project.id}/members`,
    { userId: bob.id }
  );
  log("POST /projects/:id/members (add Bob)", s7, projWithBob);
  assert(projWithBob.memberIds.includes(bob.id), "Bob is a member");

  // Remove Bob then re-add (exercise removeMember)
  const { status: s8, data: projNoBob } = await request(
    "DELETE",
    `/projects/${project.id}/members`,
    { userId: bob.id }
  );
  log("DELETE /projects/:id/members (remove Bob)", s8, projNoBob);
  assert(!projNoBob.memberIds.includes(bob.id), "Bob removed from members");

  await request("POST", `/projects/${project.id}/members`, { userId: bob.id });

  // ── 3. Tasks ────────────────────────────────────────────────────────────
  section("3. Create Tasks");

  const { status: s9, data: task1 } = await request("POST", "/tasks", {
    title: "Design API schema",
    description: "Draft the OpenAPI spec",
    projectId: project.id,
  });
  log("POST /tasks (task1)", s9, task1);
  assert(s9 === 201, "Task 1 created (201)");
  assert(task1.status === "todo", "Task starts with status 'todo'");

  const { status: s10, data: task2 } = await request("POST", "/tasks", {
    title: "Implement endpoints",
    description: "Write the route handlers",
    projectId: project.id,
  });
  log("POST /tasks (task2)", s10, task2);
  assert(s10 === 201, "Task 2 created (201)");

  // Get tasks by project
  const { status: s11, data: projectTasks } = await request(
    "GET",
    `/tasks?projectId=${project.id}`
  );
  log(`GET /tasks?projectId=${project.id}`, s11, projectTasks);
  assert(projectTasks.length === 2, "Two tasks belong to the project");

  // ── 4. Assign Tasks ─────────────────────────────────────────────────────
  section("4. Assign Tasks → task.assigned notifications");

  const { status: s12, data: assignedTask1 } = await request(
    "PUT",
    `/tasks/${task1.id}/assign`,
    { assigneeId: alice.id }
  );
  log("PUT /tasks/:id/assign (task1 → Alice)", s12, assignedTask1);
  assert(assignedTask1.assigneeId === alice.id, "Task 1 assigned to Alice");

  const { status: s13, data: assignedTask2 } = await request(
    "PUT",
    `/tasks/${task2.id}/assign`,
    { assigneeId: bob.id }
  );
  log("PUT /tasks/:id/assign (task2 → Bob)", s13, assignedTask2);
  assert(assignedTask2.assigneeId === bob.id, "Task 2 assigned to Bob");

  // ── 5. Status Transitions ───────────────────────────────────────────────
  section("5. Change Task Status → task.statusChanged notifications");

  const { status: s14, data: inProgress } = await request(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "in-progress" }
  );
  log("PUT /tasks/:id/status (todo → in-progress)", s14, inProgress);
  assert(inProgress.status === "in-progress", "Task 1 is now in-progress");

  const { status: s15, data: done } = await request(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "done" }
  );
  log("PUT /tasks/:id/status (in-progress → done)", s15, done);
  assert(done.status === "done", "Task 1 is now done");

  // Invalid backward transition
  section("5b. Invalid Status Transition (expect 400)");
  const { status: s16, data: badTransition } = await request(
    "PUT",
    `/tasks/${task1.id}/status`,
    { status: "todo" }
  );
  log("PUT /tasks/:id/status (done → todo — should fail)", s16, badTransition);
  assert(s16 === 400, "Backward transition rejected with 400");

  // ── 6. Comments ─────────────────────────────────────────────────────────
  section("6. Add Comments → comment.added notifications");

  const { status: s17, data: comment1 } = await request("POST", "/comments", {
    taskId: task1.id,
    authorId: bob.id,
    body: "Great work on this task, Alice!",
  });
  log("POST /comments (Bob on task1)", s17, comment1);
  assert(s17 === 201, "Comment 1 created (201)");
  assert(comment1.body === "Great work on this task, Alice!", "Comment body matches");

  const { status: s18, data: comment2 } = await request("POST", "/comments", {
    taskId: task2.id,
    authorId: alice.id,
    body: "Please update the request validation.",
  });
  log("POST /comments (Alice on task2)", s18, comment2);
  assert(s18 === 201, "Comment 2 created (201)");

  // Get comments by task
  const { status: s19, data: taskComments } = await request(
    "GET",
    `/comments?taskId=${task1.id}`
  );
  log(`GET /comments?taskId=${task1.id}`, s19, taskComments);
  assert(taskComments.length === 1, "One comment on task 1");

  // ── 7. Notifications ────────────────────────────────────────────────────
  section("7. Check Notifications");

  const { status: s20, data: aliceNotifs } = await request(
    "GET",
    `/notifications?userId=${alice.id}`
  );
  log(`GET /notifications?userId=${alice.id} (Alice)`, s20, aliceNotifs);
  // Alice should have: task.assigned (task1), task.statusChanged x2 (task1)
  assert(
    aliceNotifs.length >= 2,
    `Alice has at least 2 notifications (got ${aliceNotifs.length})`
  );
  assert(
    aliceNotifs.every((n: any) => n.userId === alice.id),
    "All notifications belong to Alice"
  );
  assert(
    aliceNotifs.every((n: any) => n.read === false),
    "All notifications start unread"
  );

  const { status: s21, data: bobNotifs } = await request(
    "GET",
    `/notifications?userId=${bob.id}`
  );
  log(`GET /notifications?userId=${bob.id} (Bob)`, s21, bobNotifs);
  // Bob should have: task.assigned (task2), comment.added on task1 (Bob is NOT assignee of task1, Alice is)
  // Actually Bob was assigned task2; Alice commented on task2 → Bob gets notified
  assert(
    bobNotifs.length >= 1,
    `Bob has at least 1 notification (got ${bobNotifs.length})`
  );

  // ── 8. Mark Notification as Read ────────────────────────────────────────
  section("8. Mark Notification as Read");

  const firstAliceNotif = aliceNotifs[0];
  const { status: s22, data: readNotif } = await request(
    "PUT",
    `/notifications/${firstAliceNotif.id}/read`
  );
  log(`PUT /notifications/:id/read`, s22, readNotif);
  assert(readNotif.read === true, "Notification marked as read");

  // ── 9. Get single resources ─────────────────────────────────────────────
  section("9. Single Resource Lookups");

  const { status: s23, data: fetchedTask } = await request(
    "GET",
    `/tasks/${task1.id}`
  );
  log(`GET /tasks/:id`, s23, fetchedTask);
  assert(fetchedTask.id === task1.id, "Fetched correct task by id");

  const { status: s24, data: fetchedComment } = await request(
    "GET",
    `/comments/${comment1.id}`
  );
  log(`GET /comments/:id`, s24, fetchedComment);
  assert(fetchedComment.id === comment1.id, "Fetched correct comment by id");

  const { status: s25, data: fetchedProject } = await request(
    "GET",
    `/projects/${project.id}`
  );
  log(`GET /projects/:id`, s25, fetchedProject);
  assert(fetchedProject.id === project.id, "Fetched correct project by id");

  // ── 10. Update resources ─────────────────────────────────────────────────
  section("10. Update Resources");

  const { status: s26, data: updatedTask } = await request(
    "PUT",
    `/tasks/${task2.id}`,
    { title: "Implement endpoints (revised)" }
  );
  log(`PUT /tasks/:id`, s26, updatedTask);
  assert(updatedTask.title === "Implement endpoints (revised)", "Task title updated");

  const { status: s27, data: updatedProject } = await request(
    "PUT",
    `/projects/${project.id}`,
    { description: "Alpha project — updated description" }
  );
  log(`PUT /projects/:id`, s27, updatedProject);
  assert(
    updatedProject.description === "Alpha project — updated description",
    "Project description updated"
  );

  // ── 11. 404 lookups ─────────────────────────────────────────────────────
